package com.slayerdex;

import java.util.Random;

class CatchEngine
{
    private static final int UPGRADE_GATE = 10;
    private static final int SHINY_BASE_ODDS = 4096;

    // Descending, so the first threshold the combo clears is the one that applies.
    private static final int[] COMBO_THRESHOLDS = {750, 350, 150, 50};
    private static final int[] COMBO_ODDS = {1024, 1365, 2048, 2731};

    private final Random random;

    private String comboSpecies;
    private int combo;

    CatchEngine()
    {
        this(new Random());
    }

    CatchEngine(Random random)
    {
        this.random = random;
    }

    CatchResult onKill(String species, DexEntry existing, long now)
    {
        advanceCombo(species);

        if (existing == null)
        {
            DexEntry caught = new DexEntry(species, rollIvs(), now);
            boolean shiny = rollShiny(caught);
            return new CatchResult(caught, true, null, 0, shiny, caught.isPerfect());
        }

        existing.recordKillAt(now);
        boolean wasPerfect = existing.isPerfect();

        Stat improved = null;
        int improvedFrom = 0;
        if (random.nextInt(UPGRADE_GATE) == 0)
        {
            int[] challenger = rollIvs();
            Stat stat = pickUpgrade(existing, challenger);
            if (stat != null)
            {
                improved = stat;
                improvedFrom = existing.getIv(stat);
                existing.applyUpgrade(stat, challenger[stat.ordinal()]);
            }
        }

        boolean shiny = rollShiny(existing);
        return new CatchResult(existing, false, improved, improvedFrom, shiny,
                !wasPerfect && existing.isPerfect());
    }

    void reset()
    {
        comboSpecies = null;
        combo = 0;
    }

    private void advanceCombo(String species)
    {
        if (!species.equals(comboSpecies))
        {
            comboSpecies = species;
            combo = 0;
        }
        combo++;
    }

    private int[] rollIvs()
    {
        int[] ivs = new int[DexEntry.STAT_COUNT];
        for (int i = 0; i < ivs.length; i++)
        {
            ivs[i] = random.nextInt(DexEntry.MAX_IV + 1);
        }
        return ivs;
    }

    // A stat is only eligible when the killed NPC rolled higher than the stored entry,
    // which is what stops an entry ever losing ground.
    private Stat pickUpgrade(DexEntry entry, int[] challenger)
    {
        Stat[] eligible = new Stat[DexEntry.STAT_COUNT];
        int count = 0;
        for (Stat stat : Stat.values())
        {
            if (challenger[stat.ordinal()] > entry.getIv(stat))
            {
                eligible[count++] = stat;
            }
        }
        return count == 0 ? null : eligible[random.nextInt(count)];
    }

    private boolean rollShiny(DexEntry entry)
    {
        if (entry.isShiny() || random.nextInt(shinyOdds()) != 0)
        {
            return false;
        }
        entry.markShiny();
        return true;
    }

    private int shinyOdds()
    {
        for (int i = 0; i < COMBO_THRESHOLDS.length; i++)
        {
            if (combo >= COMBO_THRESHOLDS[i])
            {
                return COMBO_ODDS[i];
            }
        }
        return SHINY_BASE_ODDS;
    }
}

package com.slayerdex;

class CatchResult
{
    private final DexEntry entry;
    private final boolean firstCatch;
    private final Stat improvedStat;
    private final int improvedFrom;
    private final boolean newShiny;
    private final boolean newPerfect;

    CatchResult(DexEntry entry, boolean firstCatch, Stat improvedStat, int improvedFrom,
                boolean newShiny, boolean newPerfect)
    {
        this.entry = entry;
        this.firstCatch = firstCatch;
        this.improvedStat = improvedStat;
        this.improvedFrom = improvedFrom;
        this.newShiny = newShiny;
        this.newPerfect = newPerfect;
    }

    DexEntry getEntry()
    {
        return entry;
    }

    boolean isFirstCatch()
    {
        return firstCatch;
    }

    Stat getImprovedStat()
    {
        return improvedStat;
    }

    int getImprovedFrom()
    {
        return improvedFrom;
    }

    boolean isNewShiny()
    {
        return newShiny;
    }

    boolean isNewPerfect()
    {
        return newPerfect;
    }

    boolean isNotable()
    {
        return firstCatch || improvedStat != null || newShiny;
    }
}

package com.slayerdex;

class DexEntry
{
    static final int STAT_COUNT = 6;
    static final int MAX_IV = 31;
    static final int PERFECT_TOTAL = STAT_COUNT * MAX_IV;

    private static final int FORMAT_VERSION = 1;

    private int version = FORMAT_VERSION;
    private String species;
    private int[] ivs;
    private boolean shiny;
    private Integer shinyKillNumber;
    private boolean firstAttemptPerfect;
    private int totalKills;
    private long firstCaught;
    private long lastKill;
    private Integer killsToPerfect;
    private Integer killsToShiny;
    private Integer killsToPerfectShiny;

    DexEntry()
    {
    }

    DexEntry(String species, int[] ivs, long caughtAt)
    {
        this.species = species;
        this.ivs = ivs;
        this.totalKills = 1;
        this.firstCaught = caughtAt;
        this.lastKill = caughtAt;
        this.firstAttemptPerfect = isPerfect();
        updateMilestones();
    }

    String getSpecies()
    {
        return species;
    }

    int getIv(Stat stat)
    {
        return ivs[stat.ordinal()];
    }

    int getIvTotal()
    {
        int total = 0;
        for (int iv : ivs)
        {
            total += iv;
        }
        return total;
    }

    boolean isPerfect()
    {
        return getIvTotal() == PERFECT_TOTAL;
    }

    boolean isShiny()
    {
        return shiny;
    }

    boolean isFirstAttemptPerfect()
    {
        return firstAttemptPerfect;
    }

    int getTotalKills()
    {
        return totalKills;
    }

    long getFirstCaught()
    {
        return firstCaught;
    }

    // Null until reached.
    Integer getShinyKillNumber()
    {
        return shinyKillNumber;
    }

    Integer getKillsToPerfect()
    {
        return killsToPerfect;
    }

    Integer getKillsToPerfectShiny()
    {
        return killsToPerfectShiny;
    }

    String getIvString()
    {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ivs.length; i++)
        {
            if (i > 0)
            {
                sb.append('/');
            }
            sb.append(ivs[i]);
        }
        return sb.toString();
    }

    // Zero on anything saved before this field existed, which is why every read goes
    // through getLastActive rather than touching it directly.
    long getLastActive()
    {
        return lastKill > 0 ? lastKill : firstCaught;
    }

    void recordKill()
    {
        totalKills++;
    }

    void recordKillAt(long now)
    {
        totalKills++;
        lastKill = now;
    }

    void applyUpgrade(Stat stat, int value)
    {
        ivs[stat.ordinal()] = value;
        updateMilestones();
    }

    void markShiny()
    {
        shiny = true;
        // shinyKillNumber is what the panel would show ("shiny on kill 412"); killsToShiny is
        // the milestone series alongside killsToPerfect. Same number, kept apart so the two
        // can diverge later without a save migration.
        shinyKillNumber = totalKills;
        killsToShiny = totalKills;
        updateMilestones();
    }

    boolean isValid()
    {
        return isUsableSpecies(species) && ivs != null && ivs.length == STAT_COUNT;
    }

    // An entity with no name in the cache comes back as the string "null" rather than as a
    // java null, so a Tempoross kill put an entry called null in the dex.
    static boolean isUsableSpecies(String species)
    {
        return species != null && !species.isEmpty() && !"null".equalsIgnoreCase(species);
    }

    private void updateMilestones()
    {
        if (killsToPerfect == null && isPerfect())
        {
            killsToPerfect = totalKills;
        }
        if (killsToPerfectShiny == null && shiny && isPerfect())
        {
            killsToPerfectShiny = totalKills;
        }
    }
}

package com.slayerdex;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.SkillColor;
import net.runelite.client.ui.components.ProgressBar;

class DexEntryDetail extends JPanel
{
    // ProgressBar hardcodes a 16px fill in paint(), so a taller bar paints only partly.
    private static final int BAR_HEIGHT = 16;

    private static final DateTimeFormatter CAUGHT_FORMAT = DateTimeFormatter
            .ofPattern("d MMM yyyy", Locale.ENGLISH)
            .withZone(ZoneId.systemDefault());

    private static final String UNREACHED = "—";

    DexEntryDetail(DexEntry entry)
    {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel column = new JPanel();
        column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
        column.setBackground(getBackground());

        JPanel bars = new JPanel(new GridLayout(Stat.values().length, 1, 0, 2));
        bars.setBackground(getBackground());
        for (Stat stat : Stat.values())
        {
            bars.add(statBar(stat, entry.getIv(stat)));
        }

        JPanel facts = new JPanel(new GridLayout(0, 1, 0, 2));
        facts.setBackground(getBackground());
        facts.add(fact("Total IVs", entry.getIvTotal() + "/" + DexEntry.PERFECT_TOTAL,
                entry.isPerfect() ? DexPalette.PERFECT : ColorScheme.TEXT_COLOR));
        facts.add(fact("Kills", Integer.toString(entry.getTotalKills()), ColorScheme.TEXT_COLOR));
        facts.add(fact("First caught", CAUGHT_FORMAT.format(Instant.ofEpochMilli(entry.getFirstCaught())),
                ColorScheme.TEXT_COLOR));
        facts.add(fact("Shiny at kill", milestone(entry.getShinyKillNumber()),
                entry.isShiny() ? DexPalette.SHINY : ColorScheme.LIGHT_GRAY_COLOR));
        facts.add(fact("Perfect at kill", milestone(entry.getKillsToPerfect()),
                entry.isPerfect() ? DexPalette.PERFECT : ColorScheme.LIGHT_GRAY_COLOR));

        if (entry.getKillsToPerfectShiny() != null)
        {
            facts.add(fact("Perfect shiny at kill", milestone(entry.getKillsToPerfectShiny()), DexPalette.PERFECT));
        }

        column.add(bars);
        column.add(Box.createRigidArea(new Dimension(0, 8)));
        column.add(facts);

        if (entry.isFirstAttemptPerfect())
        {
            JLabel note = new JLabel("Perfect on the first catch");
            note.setFont(FontManager.getRunescapeSmallFont());
            note.setForeground(DexPalette.PERFECT);
            column.add(Box.createRigidArea(new Dimension(0, 6)));
            column.add(note);
        }

        add(column, BorderLayout.NORTH);
    }

    private static ProgressBar statBar(Stat stat, int value)
    {
        ProgressBar bar = new ProgressBar();
        bar.setMaximumValue(DexEntry.MAX_IV);
        bar.setValue(value);
        bar.setBackground(DexPalette.BAR_TRACK);
        bar.setForeground(SkillColor.find(stat.getSkill()).getColor());
        bar.setLeftLabel(stat.getDisplayName());
        bar.setRightLabel(Integer.toString(value));
        bar.setPreferredSize(new Dimension(0, BAR_HEIGHT));
        bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, BAR_HEIGHT));
        return bar;
    }

    private static JPanel fact(String label, String value, Color valueColor)
    {
        JLabel name = new JLabel(label);
        name.setFont(FontManager.getRunescapeSmallFont());
        name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        JLabel read = new JLabel(value);
        read.setFont(FontManager.getRunescapeSmallFont());
        read.setForeground(valueColor);

        JPanel row = new JPanel(new BorderLayout());
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        row.add(name, BorderLayout.WEST);
        row.add(read, BorderLayout.EAST);
        return row;
    }

    private static String milestone(Integer killNumber)
    {
        return killNumber == null ? UNREACHED : Integer.toString(killNumber);
    }
}

package com.slayerdex;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

class DexEntryRow extends JPanel
{
    // Not MEDIUM_GRAY_COLOR for the dim tier, it only reaches 1.8:1 on this background.
    private static final Color IV_HIGH_COLOR = new Color(120, 200, 120);
    private static final Color IV_POOR_COLOR = new Color(140, 140, 140);

    private static final int IV_HIGH_THRESHOLD = 24;
    private static final int IV_MID_THRESHOLD = 16;
    private static final int IV_LOW_THRESHOLD = 8;

    DexEntryRow(DexEntry entry, Consumer<String> onSelect)
    {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(5, 7, 5, 7));
        setCursor(new Cursor(Cursor.HAND_CURSOR));

        setToolTipText(tooltip(entry));

        JLabel name = new JLabel(DexPalette.nameWithShiny(entry));
        name.setFont(FontManager.getRunescapeBoldFont());
        name.setForeground(DexPalette.nameColor(entry));

        JLabel kills = new JLabel(entry.getTotalKills()
                + (entry.getTotalKills() == 1 ? " kill" : " kills"));
        kills.setFont(FontManager.getRunescapeSmallFont());
        kills.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        kills.setHorizontalAlignment(SwingConstants.RIGHT);

        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(getBackground());
        header.add(name, BorderLayout.WEST);
        header.add(kills, BorderLayout.EAST);

        // As one line the labelled readout ran to 234px in a 159px column and Swing
        // ellipsised magic and hitpoints away entirely.
        JPanel grid = new JPanel(new GridLayout(2, 3, 6, 1));
        grid.setBackground(getBackground());
        for (Stat stat : Stat.values())
        {
            grid.add(statLabel(stat, entry.getIv(stat)));
        }

        JLabel total = new JLabel(entry.getIvTotal() + "/" + DexEntry.PERFECT_TOTAL);
        total.setFont(FontManager.getRunescapeSmallFont());
        total.setForeground(entry.isPerfect() ? DexPalette.PERFECT : ColorScheme.LIGHT_GRAY_COLOR);
        total.setHorizontalAlignment(SwingConstants.RIGHT);
        total.setVerticalAlignment(SwingConstants.BOTTOM);

        JPanel stats = new JPanel(new BorderLayout(6, 0));
        stats.setBackground(getBackground());
        stats.add(grid, BorderLayout.CENTER);
        stats.add(total, BorderLayout.EAST);

        JPanel body = new JPanel(new BorderLayout(0, 3));
        body.setBackground(getBackground());
        body.add(header, BorderLayout.NORTH);
        body.add(stats, BorderLayout.CENTER);

        add(body, BorderLayout.CENTER);

        // On every descendant, not just the row, or the hover dies over the stat labels.
        // Exit is bounds checked because crossing onto a child also fires one.
        MouseAdapter hover = new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                onSelect.accept(entry.getSpecies());
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                paintRow(ColorScheme.DARKER_GRAY_HOVER_COLOR);
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                Point cursor = SwingUtilities.convertPoint(
                        (Component) e.getSource(), e.getPoint(), DexEntryRow.this);
                if (!contains(cursor))
                {
                    paintRow(ColorScheme.DARKER_GRAY_COLOR);
                }
            }
        };
        listenDeep(this, hover);
    }

    private static void listenDeep(Component component, MouseAdapter listener)
    {
        component.addMouseListener(listener);
        if (component instanceof Container)
        {
            for (Component child : ((Container) component).getComponents())
            {
                listenDeep(child, listener);
            }
        }
    }

    @Override
    public Dimension getMaximumSize()
    {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }

    private static JLabel statLabel(Stat stat, int value)
    {
        JLabel label = new JLabel(stat.getShortName() + " " + value);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(ivColor(value));
        return label;
    }

    private void paintRow(Color color)
    {
        setBackground(color);
        repaintChildren(this, color);
    }

    private static void repaintChildren(Container parent, Color color)
    {
        for (Component child : parent.getComponents())
        {
            if (child instanceof JPanel)
            {
                child.setBackground(color);
                repaintChildren((Container) child, color);
            }
        }
    }

    private static Color ivColor(int value)
    {
        if (value >= DexEntry.MAX_IV)
        {
            return DexPalette.PERFECT;
        }
        if (value >= IV_HIGH_THRESHOLD)
        {
            return IV_HIGH_COLOR;
        }
        if (value >= IV_MID_THRESHOLD)
        {
            return ColorScheme.TEXT_COLOR;
        }
        if (value >= IV_LOW_THRESHOLD)
        {
            return ColorScheme.LIGHT_GRAY_COLOR;
        }
        return IV_POOR_COLOR;
    }

    private static String tooltip(DexEntry entry)
    {
        StringBuilder sb = new StringBuilder("<html>");
        for (Stat stat : Stat.values())
        {
            sb.append(stat.getDisplayName()).append(": ").append(entry.getIv(stat)).append("<br>");
        }
        if (entry.isFirstAttemptPerfect())
        {
            sb.append("<br>Perfect on the first catch");
        }
        return sb.append("</html>").toString();
    }
}

package com.slayerdex;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.image.BufferedImage;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;

class DexGuide extends JPanel
{
    private static final int PADDING = 10;
    private static final int BULLET_WIDTH = 12;

    // Deliberately not html in a JLabel. Swing treats a css width as a hint and overshoots
    // it by about a third, so the text ran past the panel edge, and its line spacing is
    // nearly double a JTextArea's.
    private static final int TEXT_WIDTH =
            PluginPanel.PANEL_WIDTH - (PluginPanel.BORDER_OFFSET * 2) - (PADDING * 2) - BULLET_WIDTH;

    private static final int ICON_SIZE = 16;

    private static final String[] POINTS = {
            "Every monster you kill is caught, once per species.",
            "A catch rolls six stats from 0 to 31.",
            "Killing that species again has a 1 in 10 chance to raise one stat toward what "
                    + "the monster rolled. Stats never go down.",
            "All six at 31 is a perfect, 186 out of 186.",
            "Shiny is a separate 1 in 4096 roll that shortens to 1 in 1024 as you chain kills "
                    + "of one species. It never changes your stats.",
            "Your dex is saved per account.",
    };

    DexGuide()
    {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(PADDING, PADDING, PADDING, PADDING));

        JLabel title = new JLabel("How it works");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(DexPalette.PERFECT);
        title.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

        JPanel points = new JPanel();
        points.setLayout(new BoxLayout(points, BoxLayout.Y_AXIS));
        points.setBackground(getBackground());
        for (int i = 0; i < POINTS.length; i++)
        {
            if (i > 0)
            {
                points.add(Box.createRigidArea(new Dimension(0, 6)));
            }
            points.add(point(POINTS[i]));
        }

        add(title, BorderLayout.NORTH);
        add(points, BorderLayout.CENTER);
    }

    @Override
    public Dimension getMaximumSize()
    {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }

    private JPanel point(String text)
    {
        JLabel bullet = new JLabel("•");
        bullet.setFont(FontManager.getRunescapeFont());
        bullet.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        bullet.setVerticalAlignment(JLabel.TOP);
        bullet.setPreferredSize(new Dimension(BULLET_WIDTH, 16));

        JTextArea body = new JTextArea(text);
        body.setFont(FontManager.getRunescapeFont());
        body.setForeground(ColorScheme.TEXT_COLOR);
        body.setBackground(getBackground());
        body.setLineWrap(true);
        body.setWrapStyleWord(true);
        body.setEditable(false);
        body.setFocusable(false);
        body.setBorder(null);

        // The panel is a fixed 225px wide, so the wrapped height can be resolved here
        // rather than left to a layout pass that has already decided this row's size.
        body.setSize(TEXT_WIDTH, Short.MAX_VALUE);
        Dimension wrapped = new Dimension(TEXT_WIDTH, body.getPreferredSize().height);
        body.setPreferredSize(wrapped);

        JPanel row = new JPanel(new BorderLayout());
        row.setBackground(getBackground());
        row.add(bullet, BorderLayout.WEST);
        row.add(body, BorderLayout.CENTER);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, wrapped.height));
        return row;
    }

    static ImageIcon questionIcon(boolean active)
    {
        return headerIcon("/help.png", active);
    }

    static ImageIcon discordIcon(boolean active)
    {
        return headerIcon("/discord.png", active);
    }

    // Both ship white. Dimming by 90 lands on 165, which is LIGHT_GRAY_COLOR, so the idle
    // state matches the rest of the header without a second file each.
    private static ImageIcon headerIcon(String resource, boolean active)
    {
        BufferedImage icon = ImageUtil.resizeImage(
                ImageUtil.loadImageResource(DexGuide.class, resource), ICON_SIZE, ICON_SIZE);
        return new ImageIcon(active ? icon : ImageUtil.luminanceOffset(icon, -90));
    }
}

package com.slayerdex;

import java.awt.Color;
import net.runelite.client.ui.ColorScheme;

final class DexPalette
{
    static final Color PERFECT = new Color(255, 200, 60);
    static final Color SHINY = new Color(120, 220, 255);

    // The xp tracker's bar track, so the two read as one client.
    static final Color BAR_TRACK = new Color(61, 56, 49);

    private DexPalette()
    {
    }

    static Color nameColor(DexEntry entry)
    {
        if (entry.isPerfect())
        {
            return PERFECT;
        }
        return entry.isShiny() ? SHINY : ColorScheme.TEXT_COLOR;
    }

    static String nameWithShiny(DexEntry entry)
    {
        return entry.isShiny() ? entry.getSpecies() + " *" : entry.getSpecies();
    }
}

package com.slayerdex;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Per-species storage scoped to the logged in RuneScape profile, so every account keeps its
 * own dex and it follows the player between clients via their RuneLite account.
 */
@Slf4j
@Singleton
class DexStore
{
    private static final String CONFIG_GROUP = "slayerdex";
    private static final String KEY_PREFIX = "entry_";

    private final ConfigManager configManager;
    private final Gson gson;

    @Inject
    DexStore(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    Map<String, DexEntry> load()
    {
        Map<String, DexEntry> collection = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);

        String profileKey = configManager.getRSProfileKey();
        if (profileKey == null)
        {
            return collection;
        }

        List<String> keys = configManager.getRSProfileConfigurationKeys(CONFIG_GROUP, profileKey, KEY_PREFIX);
        for (String key : keys)
        {
            String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, key);
            if (json == null)
            {
                continue;
            }

            try
            {
                DexEntry entry = gson.fromJson(json, DexEntry.class);
                if (entry == null || !entry.isValid())
                {
                    log.warn("SlayerDex: discarding malformed record for {}", key);
                    configManager.unsetRSProfileConfiguration(CONFIG_GROUP, key);
                    continue;
                }
                collection.put(entry.getSpecies(), entry);
            }
            catch (JsonSyntaxException e)
            {
                log.warn("SlayerDex: could not read record for {}", key, e);
            }
        }

        return collection;
    }

    boolean hasProfile()
    {
        return configManager.getRSProfileKey() != null;
    }

    boolean exists(String species)
    {
        String key = keyFor(species);
        return key != null && configManager.getRSProfileConfiguration(CONFIG_GROUP, key) != null;
    }

    void save(DexEntry entry)
    {
        String key = keyFor(entry.getSpecies());
        if (key == null)
        {
            log.warn("SlayerDex: cannot store {}, the name is not usable as a config key",
                    entry.getSpecies());
            return;
        }

        DexEntry stored = read(key);
        if (isRegression(stored, entry))
        {
            log.warn("SlayerDex: refusing to overwrite {} ({} kills, {} total) with a weaker record"
                    + " ({} kills, {} total)", entry.getSpecies(), stored.getTotalKills(),
                    stored.getIvTotal(), entry.getTotalKills(), entry.getIvTotal());
            return;
        }

        configManager.setRSProfileConfiguration(CONFIG_GROUP, key, gson.toJson(entry));
    }

    // Kills only ever increment and a stat is only ever raised, so a record that came back
    // smaller than the stored one did not come from play. It means the in memory copy was
    // stale and is about to write a fresh roll over a real grind.
    static boolean isRegression(DexEntry stored, DexEntry incoming)
    {
        if (stored == null || !stored.isValid())
        {
            return false;
        }
        return incoming.getTotalKills() < stored.getTotalKills()
                || incoming.getIvTotal() < stored.getIvTotal();
    }

    private DexEntry read(String key)
    {
        String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, key);
        if (json == null)
        {
            return null;
        }
        try
        {
            return gson.fromJson(json, DexEntry.class);
        }
        catch (JsonSyntaxException e)
        {
            return null;
        }
    }

    // ConfigManager throws on a key containing a colon. No OSRS npc name has one, but the call
    // sites are event handlers where an exception would take out kill tracking as well.
    private static String keyFor(String species)
    {
        return species.indexOf(':') == -1 ? KEY_PREFIX + species : null;
    }
}

package com.slayerdex;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

/** What the panel shows, once the search box, the filter chips and the sort are applied. */
final class DexView
{
    enum Sort
    {
        RECENT("Recently caught"),
        NAME("Name"),
        TOTAL("IV total"),
        KILLS("Kills");

        private final String label;

        Sort(String label)
        {
            this.label = label;
        }

        @Override
        public String toString()
        {
            return label;
        }
    }

    enum Filter
    {
        ALL("All"),
        PERFECT("Perfect"),
        SHINY("Shiny");

        private final String label;

        Filter(String label)
        {
            this.label = label;
        }

        String getLabel()
        {
            return label;
        }

        boolean accepts(DexEntry entry)
        {
            switch (this)
            {
                case PERFECT:
                    return entry.isPerfect();
                case SHINY:
                    return entry.isShiny();
                default:
                    return true;
            }
        }
    }

    private DexView()
    {
    }

    static List<DexEntry> apply(Collection<DexEntry> entries, String search, Filter filter, Sort sort)
    {
        String needle = search == null ? "" : search.trim().toLowerCase(Locale.ENGLISH);

        List<DexEntry> shown = new ArrayList<>();
        for (DexEntry entry : entries)
        {
            if (!filter.accepts(entry))
            {
                continue;
            }
            if (!needle.isEmpty()
                    && !entry.getSpecies().toLowerCase(Locale.ENGLISH).contains(needle))
            {
                continue;
            }
            shown.add(entry);
        }

        shown.sort(comparator(sort));
        return shown;
    }

    private static Comparator<DexEntry> comparator(Sort sort)
    {
        Comparator<DexEntry> byName = Comparator.comparing(
                DexEntry::getSpecies, String.CASE_INSENSITIVE_ORDER);

        switch (sort)
        {
            case RECENT:
                return Comparator.comparingLong(DexEntry::getLastActive).reversed().thenComparing(byName);
            case TOTAL:
                return Comparator.comparingInt(DexEntry::getIvTotal).reversed().thenComparing(byName);
            case KILLS:
                return Comparator.comparingInt(DexEntry::getTotalKills).reversed().thenComparing(byName);
            default:
                return byName;
        }
    }
}

