package com.slayerdex;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Collection;
import java.util.Collections;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.util.LinkBrowser;

class SlayerDexPanel extends PluginPanel
{
    private static final String DISCORD_URL = "https://discord.gg/zre3CtrhaS";

    private static final ImageIcon ICON_IDLE = DexGuide.questionIcon(false);
    private static final ImageIcon ICON_ACTIVE = DexGuide.questionIcon(true);
    private static final ImageIcon DISCORD_IDLE = DexGuide.discordIcon(false);
    private static final ImageIcon DISCORD_ACTIVE = DexGuide.discordIcon(true);

    private final JPanel header = new JPanel(new BorderLayout());
    private final JPanel content = new JPanel(new BorderLayout());
    private final JLabel summary = new JLabel();
    private final JPanel list = new JPanel();

    // Built once and never rebuilt. The list is torn down on every credited kill, and a
    // search box recreated mid word would drop what the player was typing.
    private final JPanel controls = new JPanel(new BorderLayout(0, 4));
    private final IconTextField search = new IconTextField();
    private final JComboBox<DexView.Sort> sort = new JComboBox<>(DexView.Sort.values());
    private final JPanel chips = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
    private DexView.Filter filter = DexView.Filter.ALL;

    // By name, not by entry: the collection is replaced wholesale on a reload.
    private String selected;
    private Collection<DexEntry> entries = Collections.emptyList();

    // An empty dex explains itself. Once there is something in it the guide steps aside
    // until asked for.
    private boolean guidePinned;

    SlayerDexPanel()
    {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        summary.setFont(FontManager.getRunescapeSmallFont());
        summary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        header.setBackground(getBackground());
        header.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

        content.setBackground(getBackground());

        list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
        list.setBackground(getBackground());

        buildControls();

        JPanel top = new JPanel(new BorderLayout());
        top.setBackground(getBackground());
        top.add(header, BorderLayout.NORTH);
        top.add(controls, BorderLayout.CENTER);

        add(top, BorderLayout.NORTH);
        add(content, BorderLayout.CENTER);
    }

    private void buildControls()
    {
        controls.setBackground(getBackground());
        controls.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

        search.setIcon(IconTextField.Icon.SEARCH);
        search.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 28));
        search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
        search.getDocument().addDocumentListener(new DocumentListener()
        {
            @Override
            public void insertUpdate(DocumentEvent e)
            {
                refresh();
            }

            @Override
            public void removeUpdate(DocumentEvent e)
            {
                refresh();
            }

            @Override
            public void changedUpdate(DocumentEvent e)
            {
                refresh();
            }
        });

        sort.setFont(FontManager.getRunescapeSmallFont());
        sort.setForeground(ColorScheme.TEXT_COLOR);
        sort.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        sort.setFocusable(false);
        sort.addItemListener(e -> refresh());

        chips.setBackground(getBackground());
        for (DexView.Filter option : DexView.Filter.values())
        {
            chips.add(chip(option));
        }

        controls.add(search, BorderLayout.NORTH);

        JPanel row = new JPanel(new BorderLayout(0, 4));
        row.setBackground(getBackground());
        row.add(sort, BorderLayout.NORTH);
        row.add(chips, BorderLayout.CENTER);
        controls.add(row, BorderLayout.CENTER);
    }

    private JLabel chip(DexView.Filter option)
    {
        JLabel label = new JLabel(option.getLabel());
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 6));
        label.setOpaque(true);
        label.setCursor(new Cursor(Cursor.HAND_CURSOR));
        paintChip(label, option);
        label.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                filter = option;
                for (Component c : chips.getComponents())
                {
                    if (c instanceof JLabel)
                    {
                        paintChip((JLabel) c, DexView.Filter.valueOf(
                                ((JLabel) c).getText().toUpperCase(java.util.Locale.ENGLISH)));
                    }
                }
                refresh();
            }
        });
        return label;
    }

    private void paintChip(JLabel label, DexView.Filter option)
    {
        boolean active = option == filter;
        label.setBackground(active ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
        label.setForeground(active ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
    }

    private void refresh()
    {
        rebuild(entries);
    }

    void update(Collection<DexEntry> entries)
    {
        SwingUtilities.invokeLater(() -> rebuild(entries));
    }

    private void rebuild(Collection<DexEntry> entries)
    {
        this.entries = entries;

        header.removeAll();
        content.removeAll();

        DexEntry open = findSelected();
        controls.setVisible(open == null && !entries.isEmpty());
        if (open == null)
        {
            selected = null;
            buildList();
        }
        else
        {
            buildDetail(open);
        }

        header.revalidate();
        header.repaint();
        content.revalidate();
        content.repaint();
    }

    private DexEntry findSelected()
    {
        if (selected == null)
        {
            return null;
        }
        for (DexEntry entry : entries)
        {
            if (selected.equals(entry.getSpecies()))
            {
                return entry;
            }
        }
        return null;
    }

    private void open(String species)
    {
        selected = species;
        rebuild(entries);
    }

    private void buildList()
    {
        list.removeAll();

        if (entries.isEmpty())
        {
            summary.setText("Nothing caught yet");
            JLabel empty = new JLabel("Kill anything to start your dex.");
            empty.setFont(FontManager.getRunescapeSmallFont());
            empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            empty.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
            list.add(empty);
        }
        else
        {
            int perfect = 0;
            int shiny = 0;
            for (DexEntry entry : entries)
            {
                if (entry.isPerfect())
                {
                    perfect++;
                }
                if (entry.isShiny())
                {
                    shiny++;
                }
            }
            summary.setText(entries.size() + " caught, " + perfect + " perfect, " + shiny + " shiny");

            java.util.List<DexEntry> shown = DexView.apply(
                    entries, search.getText(), filter, (DexView.Sort) sort.getSelectedItem());

            if (shown.isEmpty())
            {
                JLabel none = new JLabel("Nothing matches that.");
                none.setFont(FontManager.getRunescapeSmallFont());
                none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                list.add(none);
            }

            boolean first = true;
            for (DexEntry entry : shown)
            {
                if (!first)
                {
                    list.add(Box.createRigidArea(new Dimension(0, 4)));
                }
                list.add(new DexEntryRow(entry, this::open));
                first = false;
            }
        }

        if (entries.isEmpty() || guidePinned)
        {
            list.add(Box.createRigidArea(new Dimension(0, 4)));
            list.add(new DexGuide());
        }

        // A JLabel aligns left by default and a JPanel centres, and a BoxLayout reconciles
        // the two by shifting one against the other. Left throughout, so the empty message
        // starts on the same edge as everything below it.
        for (Component child : list.getComponents())
        {
            if (child instanceof JComponent)
            {
                ((JComponent) child).setAlignmentX(Component.LEFT_ALIGNMENT);
            }
        }

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        buttons.setBackground(getBackground());
        buttons.add(discordLink());
        buttons.add(guideToggle());

        header.add(summary, BorderLayout.CENTER);
        header.add(buttons, BorderLayout.EAST);
        content.add(list, BorderLayout.NORTH);
    }

    private JLabel discordLink()
    {
        JLabel discord = new JLabel(DISCORD_IDLE);
        discord.setToolTipText("Join the SlayerDex Discord");
        discord.setCursor(new Cursor(Cursor.HAND_CURSOR));
        discord.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                LinkBrowser.browse(DISCORD_URL);
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                discord.setIcon(DISCORD_ACTIVE);
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                discord.setIcon(DISCORD_IDLE);
            }
        });
        return discord;
    }

    private JLabel guideToggle()
    {
        JLabel toggle = new JLabel(guidePinned ? ICON_ACTIVE : ICON_IDLE);
        toggle.setToolTipText("How SlayerDex works");
        toggle.setCursor(new Cursor(Cursor.HAND_CURSOR));
        toggle.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 2));
        toggle.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                guidePinned = !guidePinned;
                rebuild(entries);
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                toggle.setIcon(ICON_ACTIVE);
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                toggle.setIcon(guidePinned ? ICON_ACTIVE : ICON_IDLE);
            }
        });
        return toggle;
    }

    private void buildDetail(DexEntry entry)
    {
        JLabel title = new JLabel(DexPalette.nameWithShiny(entry));
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(DexPalette.nameColor(entry));

        JPanel bar = new JPanel(new BorderLayout(0, 4));
        bar.setBackground(getBackground());
        bar.add(backLink(), BorderLayout.NORTH);
        bar.add(title, BorderLayout.CENTER);

        header.add(bar, BorderLayout.CENTER);
        content.add(new DexEntryDetail(entry), BorderLayout.NORTH);
    }

    private JLabel backLink()
    {
        JLabel back = new JLabel("< Back");
        back.setFont(FontManager.getRunescapeSmallFont());
        back.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        back.setCursor(new Cursor(Cursor.HAND_CURSOR));
        back.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                open(null);
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                back.setForeground(Color.WHITE);
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                back.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            }
        });
        return back;
    }
}

package com.slayerdex;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
        name = "SlayerDex",
        description = "Collect every monster you slay and chase perfect stats and shinies",
        tags = {"collection", "slayer", "combat", "tracker", "monster"}
)
public class SlayerDexPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private SlayerDexConfig config;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private DexStore store;

    private final CatchEngine engine = new CatchEngine();

    private final Map<Integer, Integer> myDamage = new HashMap<>();
    private final Map<Integer, Integer> totalDamage = new HashMap<>();
    private final Set<Integer> credited = new HashSet<>();

    private Map<String, DexEntry> collection = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);

    private SlayerDexPanel panel;
    private NavigationButton navButton;
    private boolean saving;

    // LOGGED_IN also fires on every region change and world hop, so without this the whole
    // collection is read back from config each time the player crosses a boundary.
    private boolean loaded;

    @Provides
    SlayerDexConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(SlayerDexConfig.class);
    }

    @Override
    protected void startUp()
    {
        panel = new SlayerDexPanel();

        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");
        navButton = NavigationButton.builder()
                .tooltip("SlayerDex")
                .icon(icon)
                .priority(6)
                .panel(panel)
                .build();
        clientToolbar.addNavigation(navButton);

        panel.update(Collections.emptyList());

        // The plugin can be switched on mid-session, which is the one path where no profile
        // event will arrive to trigger the initial load.
        if (client.getGameState() == GameState.LOGGED_IN)
        {
            clientThread.invokeLater(this::loadWhenProfileReady);
        }
    }

    @Override
    protected void shutDown()
    {
        clientToolbar.removeNavigation(navButton);
        navButton = null;
        panel = null;
        collection = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
        loaded = false;
        engine.reset();
        reset();
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        loadCollection();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        GameState state = event.getGameState();
        if (state == GameState.LOGIN_SCREEN)
        {
            collection = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
            loaded = false;
            updatePanel();
            engine.reset();
            reset();
        }
        else if (state == GameState.HOPPING)
        {
            reset();
        }
        else if (state == GameState.LOGGED_IN)
        {
            // ConfigManager only announces a profile change when the key actually changes, so
            // reconnecting to the same account is silent. Without this the collection stays
            // empty from the login screen wipe and the next kill is taken for a first catch.
            clientThread.invokeLater(this::loadWhenProfileReady);
        }
    }

    private boolean loadWhenProfileReady()
    {
        if (client.getGameState() != GameState.LOGGED_IN || loaded)
        {
            return true;
        }
        if (!store.hasProfile())
        {
            // Asking too early gets an empty collection back, which is the bug this exists to
            // avoid, so wait for the account to resolve.
            return false;
        }
        loadCollection();
        return true;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE)
        {
            return;
        }

        String boss = SubdueMessage.bossFrom(event.getMessage());
        if (boss != null)
        {
            registerKill(boss);
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event)
    {
        if (!(event.getActor() instanceof NPC))
        {
            return;
        }

        Hitsplat hitsplat = event.getHitsplat();
        boolean mine = hitsplat.isMine();

        // Poison, venom, burn and heal splats are attributed to nobody, so counting them in the
        // total would dilute the share of whoever actually did the damage. Your own venom is not
        // reported as yours, and on a long fight it is enough to lose you the kill credit.
        if (!mine && !hitsplat.isOthers())
        {
            return;
        }

        int index = ((NPC) event.getActor()).getIndex();
        int amount = hitsplat.getAmount();

        totalDamage.merge(index, amount, Integer::sum);
        if (mine)
        {
            myDamage.merge(index, amount, Integer::sum);
        }
    }

    // ActorDeath is the primary kill signal. It can occasionally be missed, so
    // onNpcDespawned re-checks any damaged NPC that left while flagged dead.
    @Subscribe
    public void onActorDeath(ActorDeath event)
    {
        if (event.getActor() instanceof NPC)
        {
            tryCredit((NPC) event.getActor());
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        NPC npc = event.getNpc();
        if (npc.isDead())
        {
            tryCredit(npc);
        }
        forget(npc.getIndex());
    }

    private void loadCollection()
    {
        // The first save on an account creates its profile, and ConfigManager announces that as a
        // profile change before it writes the value. Reloading there would drop the entry that
        // is mid-save and the next kill would catch the species fresh all over again.
        if (saving)
        {
            return;
        }

        collection = store.load();
        loaded = true;
        updatePanel();
        log.debug("SlayerDex: loaded {} species", collection.size());
    }

    private void tryCredit(NPC npc)
    {
        // Before the damage rule, or an unnamed npc that beats the rule still gets this far,
        // and one that loses it is never identified in the log.
        if (!DexEntry.isUsableSpecies(npc.getName()))
        {
            log.debug("SlayerDex: ignoring unnamed npc id {}", npc.getId());
            return;
        }

        int index = npc.getIndex();
        if (credited.contains(index))
        {
            return;
        }

        int mine = myDamage.getOrDefault(index, 0);
        if (mine <= 0)
        {
            return;
        }

        // require the majority of the damage so other players cannot steal the catch
        int total = totalDamage.getOrDefault(index, 0);
        if (mine * 2 < total)
        {
            log.debug("SlayerDex: skipped {} id {} ({} of {} damage)", npc.getName(), npc.getId(), mine, total);
            return;
        }

        credited.add(index);
        registerKill(npc.getName());
    }

    private void registerKill(String species)
    {
        CatchResult result = engine.onKill(species, collection.get(species), System.currentTimeMillis());
        DexEntry entry = result.getEntry();

        // A species we think is new but which is already on the profile means the collection
        // in memory is stale, not that the player found something. Saving would put a fresh
        // roll over a real record, so reload and let the next kill count instead.
        if (result.isFirstCatch() && store.exists(species))
        {
            log.warn("SlayerDex: {} is stored but missing from memory, reloading rather than"
                    + " overwriting it", species);
            loadCollection();
            return;
        }

        if (result.isFirstCatch())
        {
            collection.put(species, entry);
        }

        // Saved on every credited kill, not just on an improvement, so the kill count and the
        // milestone fields derived from it survive a restart.
        saving = true;
        try
        {
            store.save(entry);
        }
        finally
        {
            saving = false;
        }

        updatePanel();

        if (result.isNotable())
        {
            announce(result);
        }
    }

    private void announce(CatchResult result)
    {
        DexEntry entry = result.getEntry();
        String species = entry.getSpecies();

        if (result.isFirstCatch())
        {
            say(prefix()
                    .append(ChatColorType.NORMAL)
                    .append("Caught a new ")
                    .append(config.speciesColor(), species)
                    .append(ChatColorType.NORMAL)
                    .append(". " + entry.getIvString() + ". " + totalIvs(entry)));
        }
        else if (result.getImprovedStat() != null)
        {
            Stat stat = result.getImprovedStat();
            int from = result.getImprovedFrom();
            int to = entry.getIv(stat);
            say(prefix()
                    .append(config.speciesColor(), species)
                    .append(ChatColorType.NORMAL)
                    .append(" improved! ")
                    .append(config.improvementColor(),
                            stat.getDisplayName() + " " + from + " -> " + to + " (+" + (to - from) + ")")
                    .append(ChatColorType.NORMAL)
                    .append(". " + totalIvs(entry)));
        }

        if (result.isNewShiny())
        {
            say(prefix()
                    .append(config.shinyColor(), "Shiny " + species + "!")
                    .append(ChatColorType.NORMAL)
                    .append(" Caught on kill " + entry.getTotalKills() + "."));
        }

        if (result.isNewPerfect())
        {
            String suffix = entry.isFirstAttemptPerfect()
                    ? " on the first catch. Keep that one."
                    : " after " + entry.getTotalKills() + " kills.";
            say(prefix()
                    .append(config.perfectColor(), "Perfect " + species + "!")
                    .append(ChatColorType.NORMAL)
                    .append(" All 31s" + suffix));
        }
    }

    private ChatMessageBuilder prefix()
    {
        return new ChatMessageBuilder()
                .append(config.pluginNameColor(), "SlayerDex: ");
    }

    private static String totalIvs(DexEntry entry)
    {
        return "Total IVs " + entry.getIvTotal() + "/" + DexEntry.PERFECT_TOTAL;
    }

    private void say(ChatMessageBuilder message)
    {
        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.GAMEMESSAGE)
                .runeLiteFormattedMessage(message.build())
                .build());
    }

    private void updatePanel()
    {
        if (panel != null)
        {
            // Snapshot, because the panel rebuilds on the Swing thread while the client thread
            // keeps mutating the collection.
            panel.update(new ArrayList<>(collection.values()));
        }
    }

    private void forget(int index)
    {
        myDamage.remove(index);
        totalDamage.remove(index);
        credited.remove(index);
    }

    private void reset()
    {
        myDamage.clear();
        totalDamage.clear();
        credited.clear();
    }
}

package com.slayerdex;

import net.runelite.api.Skill;

enum Stat
{
    ATTACK("Attack", "ATK", Skill.ATTACK),
    STRENGTH("Strength", "STR", Skill.STRENGTH),
    DEFENCE("Defence", "DEF", Skill.DEFENCE),
    RANGED("Ranged", "RNG", Skill.RANGED),
    MAGIC("Magic", "MAG", Skill.MAGIC),
    HITPOINTS("Hitpoints", "HP", Skill.HITPOINTS);

    private final String displayName;
    private final String shortName;
    private final Skill skill;

    Stat(String displayName, String shortName, Skill skill)
    {
        this.displayName = displayName;
        this.shortName = shortName;
        this.skill = skill;
    }

    String getDisplayName()
    {
        return displayName;
    }

    String getShortName()
    {
        return shortName;
    }

    Skill getSkill()
    {
        return skill;
    }
}

package com.slayerdex;

import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;

/**
 * The bosses no hitsplat of yours ever lands on. Wintertodt takes damage from braziers and
 * Tempoross from cannons, so the damage rule never sees either, and the count the game
 * prints is the only signal that the player took part. Everything that is actually fought
 * still goes through hitsplats and must not match here, or it would be credited twice.
 */
final class SubdueMessage
{
    // "Your subdued Wintertodt count is: 83"
    private static final Pattern SUBDUED = Pattern.compile(
            "Your subdued (?:<col=[0-9a-fA-F]{6}>)?(?<boss>.+?)(?:</col>)? count is: ?"
                    + "(?:<col=[0-9a-fA-F]{6}>)?[0-9,]+");

    // "Your Tempoross kill count is: 2". Ordinary wording, so the name has to be checked
    // against the list below rather than the phrasing.
    private static final Pattern KILL_COUNT = Pattern.compile(
            "Your (?:<col=[0-9a-fA-F]{6}>)?(?<boss>.+?)(?:</col>)? kill count is: ?"
                    + "(?:<col=[0-9a-fA-F]{6}>)?[0-9,]+");

    private static final Set<String> BY_KILL_COUNT;

    static
    {
        Set<String> bosses = new HashSet<>();
        bosses.add("tempoross");
        BY_KILL_COUNT = Collections.unmodifiableSet(bosses);
    }

    private SubdueMessage()
    {
    }

    @Nullable
    static String bossFrom(String message)
    {
        String subdued = match(SUBDUED, message);
        if (subdued != null)
        {
            return subdued;
        }

        String killed = match(KILL_COUNT, message);
        return killed != null && BY_KILL_COUNT.contains(killed.toLowerCase(Locale.ENGLISH))
                ? killed
                : null;
    }

    @Nullable
    private static String match(Pattern pattern, String message)
    {
        Matcher matcher = pattern.matcher(message);
        if (!matcher.find())
        {
            return null;
        }

        String boss = matcher.group("boss").trim();
        return DexEntry.isUsableSpecies(boss) ? boss : null;
    }
}

package com.slayerdex;

import java.util.Random;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CatchEngineTest
{
    private static final String GOBLIN = "Goblin";

    @Test
    public void freshCatchRollsEveryStatInRange()
    {
        CatchEngine engine = new CatchEngine(new Random(1));

        for (int i = 0; i < 500; i++)
        {
            DexEntry entry = engine.onKill(GOBLIN + i, null, 0L).getEntry();
            for (Stat stat : Stat.values())
            {
                int iv = entry.getIv(stat);
                assertTrue(iv >= 0 && iv <= DexEntry.MAX_IV);
            }
            assertEquals(1, entry.getTotalKills());
        }
    }

    @Test
    public void entryNeverLosesGround()
    {
        CatchEngine engine = new CatchEngine(new Random(7));
        DexEntry entry = engine.onKill(GOBLIN, null, 0L).getEntry();

        int[] previous = snapshot(entry);
        for (int kill = 0; kill < 20_000; kill++)
        {
            engine.onKill(GOBLIN, entry, 0L);
            int[] current = snapshot(entry);
            for (Stat stat : Stat.values())
            {
                assertTrue(current[stat.ordinal()] >= previous[stat.ordinal()]);
            }
            previous = current;
        }
    }

    @Test
    public void anUpgradeMovesExactlyOneStat()
    {
        CatchEngine engine = new CatchEngine(new Random(11));
        DexEntry entry = engine.onKill(GOBLIN, null, 0L).getEntry();

        int upgrades = 0;
        for (int kill = 0; kill < 20_000; kill++)
        {
            int[] before = snapshot(entry);
            CatchResult result = engine.onKill(GOBLIN, entry, 0L);
            int[] after = snapshot(entry);

            int changed = 0;
            for (int i = 0; i < before.length; i++)
            {
                if (before[i] != after[i])
                {
                    changed++;
                }
            }

            if (result.getImprovedStat() == null)
            {
                assertEquals(0, changed);
            }
            else
            {
                assertEquals(1, changed);
                Stat stat = result.getImprovedStat();
                assertEquals(before[stat.ordinal()], result.getImprovedFrom());
                assertTrue(after[stat.ordinal()] > result.getImprovedFrom());
                upgrades++;
            }
        }

        assertTrue(upgrades > 0);
    }

    @Test
    public void killCountTracksEveryKillNotJustUpgrades()
    {
        CatchEngine engine = new CatchEngine(new Random(3));
        DexEntry entry = engine.onKill(GOBLIN, null, 0L).getEntry();

        for (int kill = 0; kill < 250; kill++)
        {
            engine.onKill(GOBLIN, entry, 0L);
        }

        assertEquals(251, entry.getTotalKills());
    }

    @Test
    public void shinyPreservesStatsAndOnlyTriggersOnce()
    {
        CatchEngine engine = new CatchEngine(new AlwaysShinyRandom());
        CatchResult first = engine.onKill(GOBLIN, null, 0L);
        DexEntry entry = first.getEntry();

        assertTrue(first.isNewShiny());
        assertTrue(entry.isShiny());
        assertTrue(entry.isFirstAttemptPerfect());
        assertEquals("31/31/31/31/31/31", entry.getIvString());

        CatchResult second = engine.onKill(GOBLIN, entry, 0L);
        assertFalse(second.isNewShiny());
        assertTrue(entry.isShiny());
        assertEquals("31/31/31/31/31/31", entry.getIvString());
    }

    @Test
    public void firstCatchIsReportedOnlyOnce()
    {
        CatchEngine engine = new CatchEngine(new Random(5));

        CatchResult first = engine.onKill(GOBLIN, null, 0L);
        assertTrue(first.isFirstCatch());
        assertTrue(first.isNotable());
        assertNull(first.getImprovedStat());

        CatchResult second = engine.onKill(GOBLIN, first.getEntry(), 0L);
        assertFalse(second.isFirstCatch());
        assertNotNull(second.getEntry());
    }

    @Test
    public void newPerfectIsAnnouncedOnTheKillThatCompletesTheSet()
    {
        CatchEngine engine = new CatchEngine(new Random(13));
        DexEntry entry = engine.onKill(GOBLIN, null, 0L).getEntry();

        int announcements = 0;
        for (int kill = 0; kill < 20_000; kill++)
        {
            if (engine.onKill(GOBLIN, entry, 0L).isNewPerfect())
            {
                announcements++;
            }
        }

        assertTrue(entry.isPerfect());
        assertEquals(1, announcements);
    }

    private static int[] snapshot(DexEntry entry)
    {
        int[] ivs = new int[DexEntry.STAT_COUNT];
        for (Stat stat : Stat.values())
        {
            ivs[stat.ordinal()] = entry.getIv(stat);
        }
        return ivs;
    }

    /**
     * Returns the top of any small roll and zero for the shiny roll, giving a perfect shiny on
     * the first kill without needing to know the order the engine draws in.
     */
    private static final class AlwaysShinyRandom extends Random
    {
        @Override
        public int nextInt(int bound)
        {
            return bound >= 1024 ? 0 : bound - 1;
        }
    }
}

package com.slayerdex;

import com.google.gson.Gson;
import net.runelite.http.api.RuneLiteAPI;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class DexEntryTest
{
    private static final Gson GSON = RuneLiteAPI.GSON;

    @Test
    public void roundTripPreservesRecord()
    {
        DexEntry entry = new DexEntry("Goblin", new int[]{12, 31, 8, 0, 4, 22}, 1717459200000L);
        entry.recordKill();
        entry.applyUpgrade(Stat.DEFENCE, 27);
        entry.markShiny();

        DexEntry restored = GSON.fromJson(GSON.toJson(entry), DexEntry.class);

        assertTrue(restored.isValid());
        assertEquals("Goblin", restored.getSpecies());
        assertEquals("12/31/27/0/4/22", restored.getIvString());
        assertEquals(entry.getIvTotal(), restored.getIvTotal());
        assertEquals(2, restored.getTotalKills());
        assertTrue(restored.isShiny());
        assertFalse(restored.isFirstAttemptPerfect());
    }

    @Test
    public void roundTripKeepsUnreachedMilestonesNull()
    {
        DexEntry entry = new DexEntry("Goblin", new int[]{1, 1, 1, 1, 1, 1}, 0L);

        DexEntry restored = GSON.fromJson(GSON.toJson(entry), DexEntry.class);

        assertFalse(restored.isPerfect());
        assertFalse(restored.isShiny());
        assertEquals(1, restored.getTotalKills());
    }

    @Test
    public void anUnnamedEntityIsNotASpecies()
    {
        // The cache returns the string "null" for anything without a name, which is how a
        // Tempoross kill produced an entry called null.
        assertFalse(DexEntry.isUsableSpecies("null"));
        assertFalse(DexEntry.isUsableSpecies("NULL"));
        assertFalse(DexEntry.isUsableSpecies(null));
        assertFalse(DexEntry.isUsableSpecies(""));
        assertTrue(DexEntry.isUsableSpecies("Tempoross"));
        assertTrue(DexEntry.isUsableSpecies("Goblin"));
    }

    @Test
    public void aRecordNamedNullIsDiscardedOnLoad()
    {
        DexEntry unnamed = GSON.fromJson(
                "{\"species\":\"null\",\"ivs\":[7,9,24,9,28,20],\"totalKills\":1}", DexEntry.class);

        assertFalse(unnamed.isValid());
    }

    @Test
    public void malformedRecordIsRejected()
    {
        assertFalse(GSON.fromJson("{\"species\":\"Goblin\"}", DexEntry.class).isValid());
        assertFalse(GSON.fromJson("{\"ivs\":[1,2,3]}", DexEntry.class).isValid());
        assertNotNull(GSON.fromJson("{}", DexEntry.class));
    }

    @Test
    public void perfectFreshCatchIsFlaggedOnTheFirstKill()
    {
        DexEntry entry = new DexEntry("Goblin", new int[]{31, 31, 31, 31, 31, 31}, 0L);

        assertTrue(entry.isPerfect());
        assertTrue(entry.isFirstAttemptPerfect());
        assertEquals(DexEntry.PERFECT_TOTAL, entry.getIvTotal());
    }

    @Test
    public void upgradeThatCompletesTheSetRecordsTheMilestone()
    {
        DexEntry entry = new DexEntry("Goblin", new int[]{31, 31, 31, 31, 31, 30}, 0L);
        assertFalse(entry.isFirstAttemptPerfect());

        entry.recordKill();
        entry.applyUpgrade(Stat.HITPOINTS, 31);

        assertTrue(entry.isPerfect());
        assertFalse(entry.isFirstAttemptPerfect());
    }
}

package com.slayerdex;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Regression cover for the overwrite reported in issue 1, where a reconnect left the
 * collection empty, the next kill was taken for a first catch, and a fresh roll was written
 * over a perfect record.
 */
public class DexStoreTest
{
    private static DexEntry perfectAfterAGrind()
    {
        DexEntry entry = new DexEntry("Venator", new int[]{31, 31, 31, 31, 31, 31}, 1717459200000L);
        for (int i = 1; i < 800; i++)
        {
            entry.recordKill();
        }
        return entry;
    }

    private static DexEntry freshRoll()
    {
        return new DexEntry("Venator", new int[]{12, 4, 22, 8, 0, 19}, 1717459200000L);
    }

    @Test
    public void aFreshRollNeverOverwritesAGrind()
    {
        assertTrue(DexStore.isRegression(perfectAfterAGrind(), freshRoll()));
    }

    @Test
    public void fewerKillsIsARegressionEvenAtEqualStats()
    {
        DexEntry stored = perfectAfterAGrind();
        DexEntry incoming = new DexEntry("Venator", new int[]{31, 31, 31, 31, 31, 31}, 1717459200000L);

        assertTrue(DexStore.isRegression(stored, incoming));
    }

    @Test
    public void lowerStatsAreARegressionEvenAtEqualKills()
    {
        DexEntry stored = new DexEntry("Venator", new int[]{31, 31, 31, 31, 31, 31}, 0L);
        DexEntry incoming = new DexEntry("Venator", new int[]{31, 31, 31, 31, 31, 30}, 0L);

        assertTrue(DexStore.isRegression(stored, incoming));
    }

    @Test
    public void normalProgressIsNotARegression()
    {
        DexEntry stored = new DexEntry("Venator", new int[]{31, 31, 31, 31, 31, 30}, 0L);

        DexEntry improved = new DexEntry("Venator", new int[]{31, 31, 31, 31, 31, 30}, 0L);
        improved.recordKill();
        improved.applyUpgrade(Stat.HITPOINTS, 31);

        assertFalse(DexStore.isRegression(stored, improved));
    }

    @Test
    public void anotherKillWithNoUpgradeIsNotARegression()
    {
        DexEntry stored = new DexEntry("Venator", new int[]{12, 4, 22, 8, 0, 19}, 0L);

        DexEntry sameButOneMoreKill = new DexEntry("Venator", new int[]{12, 4, 22, 8, 0, 19}, 0L);
        sameButOneMoreKill.recordKill();

        assertFalse(DexStore.isRegression(stored, sameButOneMoreKill));
    }

    @Test
    public void aGenuinelyNewSpeciesIsNotARegression()
    {
        assertFalse(DexStore.isRegression(null, freshRoll()));
    }

    @Test
    public void aMalformedStoredRecordDoesNotBlockSaving()
    {
        DexEntry malformed = new DexEntry();

        assertFalse(malformed.isValid());
        assertFalse(DexStore.isRegression(malformed, freshRoll()));
    }
}

package com.slayerdex;

import com.slayerdex.DexView.Filter;
import com.slayerdex.DexView.Sort;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class DexViewTest
{
    private static final long DAY = 86_400_000L;

    private static DexEntry entry(String name, int[] ivs, int kills, long caught, long last)
    {
        DexEntry e = new DexEntry(name, ivs, caught);
        for (int i = 1; i < kills; i++)
        {
            e.recordKillAt(last);
        }
        return e;
    }

    private static List<DexEntry> sample()
    {
        DexEntry rat = entry("Rat", new int[]{31, 31, 31, 31, 31, 31}, 800, DAY, DAY * 2);
        DexEntry goblin = entry("Goblin", new int[]{12, 4, 22, 8, 0, 19}, 40, DAY * 3, DAY * 9);
        DexEntry spectre = entry("Aberrant spectre", new int[]{28, 21, 19, 31, 4, 30}, 120, DAY * 5, DAY * 5);
        spectre.markShiny();
        return Arrays.asList(rat, goblin, spectre);
    }

    private static String names(List<DexEntry> entries)
    {
        StringBuilder sb = new StringBuilder();
        for (DexEntry e : entries)
        {
            if (sb.length() > 0)
            {
                sb.append(", ");
            }
            sb.append(e.getSpecies());
        }
        return sb.toString();
    }

    @Test
    public void recentPutsTheLastThingYouKilledOnTop()
    {
        assertEquals("Goblin, Aberrant spectre, Rat",
                names(DexView.apply(sample(), "", Filter.ALL, Sort.RECENT)));
    }

    @Test
    public void nameSortsAlphabeticallyIgnoringCase()
    {
        assertEquals("Aberrant spectre, Goblin, Rat",
                names(DexView.apply(sample(), "", Filter.ALL, Sort.NAME)));
    }

    @Test
    public void totalPutsTheBestFirst()
    {
        assertEquals("Rat, Aberrant spectre, Goblin",
                names(DexView.apply(sample(), "", Filter.ALL, Sort.TOTAL)));
    }

    @Test
    public void killsPutsTheMostGroundFirst()
    {
        assertEquals("Rat, Aberrant spectre, Goblin",
                names(DexView.apply(sample(), "", Filter.ALL, Sort.KILLS)));
    }

    @Test
    public void searchMatchesPartOfTheNameInAnyCase()
    {
        assertEquals("Aberrant spectre", names(DexView.apply(sample(), "spec", Filter.ALL, Sort.NAME)));
        assertEquals("Aberrant spectre", names(DexView.apply(sample(), "ABERRANT", Filter.ALL, Sort.NAME)));
        assertEquals("", names(DexView.apply(sample(), "dragon", Filter.ALL, Sort.NAME)));
    }

    @Test
    public void filtersNarrowToPerfectAndShiny()
    {
        assertEquals("Rat", names(DexView.apply(sample(), "", Filter.PERFECT, Sort.NAME)));
        assertEquals("Aberrant spectre", names(DexView.apply(sample(), "", Filter.SHINY, Sort.NAME)));
    }

    @Test
    public void searchAndFilterCombine()
    {
        assertEquals("", names(DexView.apply(sample(), "rat", Filter.SHINY, Sort.NAME)));
        assertEquals("Rat", names(DexView.apply(sample(), "rat", Filter.PERFECT, Sort.NAME)));
    }

    @Test
    public void aRecordSavedBeforeLastKillExistedStillSortsByRecent()
    {
        // lastKill is zero on those, so getLastActive falls back to when it was first caught.
        DexEntry old = new DexEntry("Man", new int[]{1, 1, 1, 1, 1, 1}, DAY * 20);
        DexEntry legacy = new com.google.gson.Gson().fromJson(
                "{\"species\":\"Duck\",\"ivs\":[2,2,2,2,2,2],\"totalKills\":1,\"firstCaught\":"
                        + (DAY * 30) + "}", DexEntry.class);

        assertTrue(legacy.getLastActive() > 0);
        assertEquals("Duck, Man",
                names(DexView.apply(Arrays.asList(old, legacy), "", Filter.ALL, Sort.RECENT)));
    }
}

package com.slayerdex;

import java.util.Arrays;
import java.util.Random;

/**
 * Standalone reference that measures how long the grind to a perfect entry actually takes.
 * Not part of the plugin. Run with: ./gradlew -q runGrindSim
 */
public class GrindSim
{
    private static final int TRIALS = 100_000;
    private static final String SPECIES = "Goblin";

    public static void main(String[] args)
    {
        int trials = args.length > 0 ? Integer.parseInt(args[0]) : TRIALS;
        long seed = args.length > 1 ? Long.parseLong(args[1]) : 20240604L;

        Random seeds = new Random(seed);
        int[] killsToPerfect = new int[trials];
        int firstAttemptPerfect = 0;

        for (int i = 0; i < trials; i++)
        {
            CatchEngine engine = new CatchEngine(new Random(seeds.nextLong()));
            DexEntry entry = engine.onKill(SPECIES, null, 0L).getEntry();
            if (entry.isPerfect())
            {
                firstAttemptPerfect++;
            }

            int kills = 1;
            while (!entry.isPerfect())
            {
                engine.onKill(SPECIES, entry, 0L);
                kills++;
            }
            killsToPerfect[i] = kills;
        }

        Arrays.sort(killsToPerfect);
        System.out.printf("trials            %d%n", trials);
        System.out.printf("mean              %.0f%n", Arrays.stream(killsToPerfect).average().orElse(0));
        System.out.printf("p10               %d%n", percentile(killsToPerfect, 10));
        System.out.printf("median            %d%n", percentile(killsToPerfect, 50));
        System.out.printf("p90               %d%n", percentile(killsToPerfect, 90));
        System.out.printf("p99               %d%n", percentile(killsToPerfect, 99));
        System.out.printf("max               %d%n", killsToPerfect[trials - 1]);
        System.out.printf("first-attempt 186 %d of %d%n", firstAttemptPerfect, trials);
    }

    private static int percentile(int[] sorted, int p)
    {
        int index = (int) Math.ceil(p / 100.0 * sorted.length) - 1;
        return sorted[Math.max(0, index)];
    }
}

package com.slayerdex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Covers the states a player cannot reach on demand. A shiny is 1 in 4096 and a perfect
 * is around 800 kills, so the branches that render them are never exercised by hand and
 * would otherwise first run on somebody else's machine.
 */
public class PanelRenderTest
{
    private static final int[] PERFECT = {31, 31, 31, 31, 31, 31};
    private static final int[] MIDDLING = {12, 31, 8, 0, 4, 22};

    @Test
    public void theHelpIconResolvesItsResource()
    {
        // ICON_IDLE and ICON_ACTIVE are static finals on the panel. A wrong resource path
        // throws in the initialiser, which takes the whole panel down on startup rather
        // than only when the guide is opened.
        assertNotNull(DexGuide.questionIcon(true));
        assertNotNull(DexGuide.questionIcon(false));
        assertEquals(16, DexGuide.questionIcon(true).getIconWidth());
        assertEquals(16, DexGuide.questionIcon(true).getIconHeight());
    }

    @Test
    public void theGuideBuilds()
    {
        assertNotNull(new DexGuide());
    }

    @Test
    public void theDetailViewBuildsForEveryMilestoneCombination()
    {
        assertNotNull(new DexEntryDetail(plain()));
        assertNotNull(new DexEntryDetail(perfectOnly()));
        assertNotNull(new DexEntryDetail(shinyOnly()));
        assertNotNull(new DexEntryDetail(perfectThenShiny()));
        assertNotNull(new DexEntryDetail(shinyThenPerfect()));
        assertNotNull(new DexEntryDetail(firstAttemptPerfect()));
    }

    @Test
    public void shinyOnAPerfectEntryKeepsTheStatsAndStampsPerfectShiny()
    {
        DexEntry entry = perfectThenShiny();

        assertTrue(entry.isPerfect());
        assertTrue(entry.isShiny());
        assertEquals("31/31/31/31/31/31", entry.getIvString());
        assertEquals(Integer.valueOf(1), entry.getKillsToPerfect());
        assertEquals(Integer.valueOf(3), entry.getShinyKillNumber());
        assertEquals(Integer.valueOf(3), entry.getKillsToPerfectShiny());
    }

    @Test
    public void perfectOnAShinyEntryStampsPerfectShinyAtTheLaterKill()
    {
        DexEntry entry = shinyThenPerfect();

        assertEquals(Integer.valueOf(1), entry.getShinyKillNumber());
        assertEquals(Integer.valueOf(2), entry.getKillsToPerfect());
        assertEquals(Integer.valueOf(2), entry.getKillsToPerfectShiny());
    }

    @Test
    public void unreachedMilestonesStayNullRatherThanZero()
    {
        DexEntry entry = plain();

        assertNull(entry.getKillsToPerfect());
        assertNull(entry.getShinyKillNumber());
        assertNull(entry.getKillsToPerfectShiny());
    }

    private static DexEntry plain()
    {
        return new DexEntry("Goblin", MIDDLING.clone(), 1717459200000L);
    }

    private static DexEntry perfectOnly()
    {
        return new DexEntry("Goblin", PERFECT.clone(), 1717459200000L);
    }

    private static DexEntry shinyOnly()
    {
        DexEntry entry = plain();
        entry.markShiny();
        return entry;
    }

    private static DexEntry perfectThenShiny()
    {
        DexEntry entry = perfectOnly();
        entry.recordKill();
        entry.recordKill();
        entry.markShiny();
        return entry;
    }

    private static DexEntry shinyThenPerfect()
    {
        DexEntry entry = new DexEntry("Goblin", new int[]{31, 31, 31, 31, 31, 30}, 1717459200000L);
        entry.markShiny();
        entry.recordKill();
        entry.applyUpgrade(Stat.HITPOINTS, 31);
        return entry;
    }

    private static DexEntry firstAttemptPerfect()
    {
        return new DexEntry("Goblin", PERFECT.clone(), 1717459200000L);
    }
}

