package com.slayerdex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class SubdueMessageTest
{
    @Test
    public void readsTheRealMessagesTheGameSends()
    {
        // Both copied verbatim from a client log. They do not share a format: Wintertodt is
        // subdued, Tempoross reports an ordinary kill count.
        assertEquals("Wintertodt", SubdueMessage.bossFrom(
                "Your subdued Wintertodt count is: <col=ff0000>83</col>."));
        assertEquals("Tempoross", SubdueMessage.bossFrom(
                "Your Tempoross kill count is: <col=ff0000>2</col>."));
    }

    @Test
    public void readsTheBossFromASubdueCount()
    {
        assertEquals("Wintertodt", SubdueMessage.bossFrom(
                "Your subdued Wintertodt count is: <col=ff0000>82</col>"));
        assertEquals("Tempoross", SubdueMessage.bossFrom(
                "Your subdued Tempoross count is: <col=ff0000>7</col>"));
    }

    @Test
    public void copesWithColourTagsAroundTheName()
    {
        assertEquals("Wintertodt", SubdueMessage.bossFrom(
                "Your subdued <col=ff0000>Wintertodt</col> count is: <col=ff0000>1,204</col>"));
    }

    @Test
    public void ignoresEveryOtherKillCount()
    {
        // These are fought, so the damage rule already credits them. Matching the kill count
        // wording generally would credit them a second time.
        assertNull(SubdueMessage.bossFrom("Your Zalcano kill count is: <col=ff0000>41</col>"));
        assertNull(SubdueMessage.bossFrom("Your Zulrah kill count is: <col=ff0000>500</col>"));
        assertNull(SubdueMessage.bossFrom("Your Vorkath kill count is: <col=ff0000>73</col>"));
        assertNull(SubdueMessage.bossFrom("Your General Graardor kill count is: <col=ff0000>9</col>"));
        assertNull(SubdueMessage.bossFrom(
                "Your completion count for Chambers of Xeric is: <col=ff0000>12</col>"));
    }

    @Test
    public void ignoresUnrelatedChatter()
    {
        assertNull(SubdueMessage.bossFrom("You subdued the Wintertodt!"));
        assertNull(SubdueMessage.bossFrom("Your Slayer task is complete."));
        assertNull(SubdueMessage.bossFrom(""));
    }
}
